-- HeRoShield Supabase / PostgreSQL bootstrap (non-destructive)
-- IMPORTANT: This is a compatibility baseline, NOT a verified exact production schema.
-- Back up Supabase first. Existing tables and data are never dropped.
-- Tables with the same name but different columns may need manual migration.
BEGIN;
CREATE TABLE IF NOT EXISTS public.detections (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, server_id uuid, player text, identifier text, reason text, info text, action text, identifiers jsonb, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS public.hs_logs (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, server_name text, type text, detail text, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS public.hs_players (server_name text, identifier text, name text, playtime_sec bigint DEFAULT 0, online boolean DEFAULT false, last_seen timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS public.hs_servers (name text PRIMARY KEY, online integer DEFAULT 0, max integer DEFAULT 0);
CREATE TABLE IF NOT EXISTS public.leaderboard_optins (discord_id text PRIMARY KEY, opted_in boolean NOT NULL DEFAULT true, updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS public.scan_pins (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, pin text UNIQUE, license_id text, used boolean DEFAULT false, report jsonb, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS public.scanner_licenses (id text PRIMARY KEY, owner_discord text, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS public.user_access (discord_id text PRIMARY KEY, name text, avatar text, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS public.hs_settings (key text PRIMARY KEY, value jsonb);
CREATE TABLE IF NOT EXISTS public.hs_blacklist (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, identifier text, reason text, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS public.hs_abandoned_scans (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, noticed_at timestamptz DEFAULT now(), detail jsonb);
CREATE TABLE IF NOT EXISTS public.hs_client_webhooks (owner_discord text PRIMARY KEY, webhook_url text);
CREATE TABLE IF NOT EXISTS public.hs_owner_machines (owner_discord text NOT NULL, ident text NOT NULL, created_at timestamptz DEFAULT now(), PRIMARY KEY(owner_discord,ident));
CREATE TABLE IF NOT EXISTS public.hs_account_licenses (id text PRIMARY KEY, claimed_discord text, discord_user_id text, enterprise boolean DEFAULT false, seats integer DEFAULT 1, expires_at timestamptz, revoked boolean DEFAULT false, enterprise_name text);
CREATE TABLE IF NOT EXISTS public.cheat_servers (owner_discord text NOT NULL, guild_id text NOT NULL, PRIMARY KEY(owner_discord,guild_id));
CREATE TABLE IF NOT EXISTS public.paid_entitlements (discord_id text PRIMARY KEY, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS public.billing_payments (stripe_payment_id text PRIMARY KEY, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS public.partners (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, guild_id text UNIQUE, name text, icon text, members integer DEFAULT 0, description text, invite text, position integer DEFAULT 0, created_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS hs_detections_created_idx ON public.detections(created_at DESC);
CREATE INDEX IF NOT EXISTS hs_logs_created_idx ON public.hs_logs(created_at DESC);
CREATE INDEX IF NOT EXISTS hs_players_last_seen_idx ON public.hs_players(last_seen DESC);
CREATE INDEX IF NOT EXISTS hs_pins_used_created_idx ON public.scan_pins(created_at DESC) WHERE used = true AND report IS NOT NULL;
CREATE INDEX IF NOT EXISTS hs_pins_license_idx ON public.scan_pins(license_id);
CREATE INDEX IF NOT EXISTS hs_licenses_owner_idx ON public.scanner_licenses(owner_discord);
COMMIT;
-- SECURITY: Do not enable permissive RLS policies or expose service-role keys in frontend.
-- Existing database schemas must be checked against api/*.js before production deployment.
